pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20 token that always succeeds on transferFrom
        address token = address(new SimpleToken());
        address from = address(0x1234);
        address[] memory tos = new address[](1);
        tos[0] = address(0x5678);
        uint amount = 100;
        // Ensure from has allowance: prank as token owner and approve
        vm.prank(address(0xdead));
        SimpleToken(token).approve(from, amount);
        // Call the transfer function
        bool result = c.transfer(from, token, tos, amount);
        // Reference returns true; buggy returns false
        assertTrue(result == true);
    }
}

contract SimpleToken {
    mapping(address => mapping(address => uint)) public allowance;
    function approve(address spender, uint amount) external {
        allowance[msg.sender][spender] = amount;
    }
    function transferFrom(address, address, uint) external returns (bool) {
        return true;
    }
}

