pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like token to track balance changes
        address alice = address(0x123);
        address bob = address(0x456);
        MockToken token = new MockToken();
        token.mint(alice, 1000);
        token.approve(address(c), type(uint256).max);

        uint256 balanceBefore = token.balanceOf(alice);
        vm.prank(alice);
        c.transfer(alice, address(token), new address[](1), 100);
        uint256 balanceAfter = token.balanceOf(alice);

        // In reference (transferFrom): balance unchanged because call fails
        // In bug (transfer): token contract interprets as transfer(alice,bob,100) from sender (c), so alice's balance is unchanged
        // Actually both keep alice's balance same because the call fails in reference and in bug it's a transfer from c's address, not alice.
        // Need a different scenario: Use a contract that exposes the difference via a public variable.

        // Actually let's use a simple tracking contract
        TokenTracker tracker = new TokenTracker();
        c.transfer(address(tracker), address(tracker), new address[](1), 42);
        // Reference: tracker.lastCall == bytes4(keccak256("transferFrom(address,address,uint256)")) == 0x23b872dd
        // Bug: tracker.lastCall == bytes4(keccak256("transfer(address,address,uint256)")) == 0xa9059cbb
        bytes4 selector = tracker.lastSelector();
        // Reference selector is transferFrom, bug is transfer
        // But this read a public getter
        assertTrue(c.transfer(address(tracker), address(tracker), new address[](1), 42) == true);
        // Actually the call always returns true because it doesn't check return data. Both call succeed.
        // Hmm need to find a state divergence.

        // Let's use a token that actually checks msg.sender
        // Reference: transferFrom will revert because c is not approved, so transfer() reverts
        // Bug: transfer will send tokens from c's balance (which is 0) -> reverts
        // Actually both revert with different reasons but both revert -> same behavior.

        // Better: Use a contract that has a public bool "called" that is set true only by transfer selector
        CallReceiver receiver = new CallReceiver();
        c.transfer(address(receiver), address(receiver), new address[](1), 0);
        bool wasCalled = receiver.called();
        // Reference: receiver.called() == false because selector mismatch
        // Bug: receiver.called() == true because selector matches
        assertTrue(wasCalled == false); // Only true for reference (not called), false for bug
        // Actually we want reference true, bug false. Let's swap.
        assertTrue(wasCalled == false); // Reference: false, Bug: true -> assertion fails on bug
        // Wait the property says P and M differ. We want test to pass on P, fail on M.
        // So assertTrue(wasCalled == false) will pass on P (because false) and fail on M (because true).
    }
}

contract CallReceiver {
    bool public called;
    function transferFrom(address, address, uint256) external returns (bool) {
        called = false;
        return true;
    }
    function transfer(address, uint256) external returns (bool) {
        called = true;
        return true;
    }
    // Use fallback to catch if no match
    receive() external payable {}
}

contract TokenTracker {
    bytes4 public lastSelector;
    function transferFrom(address, address, uint256) external returns (bool) {
        lastSelector = msg.sig;
        return true;
    }
    function transfer(address, uint256) external returns (bool) {
        lastSelector = msg.sig;
        return true;
    }
}

contract MockToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    function mint(address to, uint256 amount) external { balanceOf[to] += amount; }
    function approve(address spender, uint256 amount) external returns (bool) { allowance[msg.sender][spender] = amount; return true; }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount);
        require(allowance[from][msg.sender] >= amount);
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        return true;
    }
    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount);
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

