pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a minimal token that responds to transferFrom selector by doing nothing (success),
        // but reverts on any other call including the buggy 'transfer' selector.
        TokenMock dummyToken = new TokenMock();
        address alice = address(0x1111);
        address bob = address(0x2222);
        address[] memory tos = new address[](1);
        tos[0] = bob;

        // Call transfer, which will use either transferFrom or transfer depending on contract
        bool success;
        try c.transfer(alice, address(dummyToken), tos, 100) {
            success = true;
        } catch {
            success = false;
        }

        // Reference: transferFrom selector is called, dummyToken handles it (returns true, no revert) -> c.transfer returns true
        // Bug: transfer selector is called, dummyToken's fallback calls self.transfer which reverts -> c.transfer reverts, so success == false
        assertTrue(success == true);
    }
}

contract TokenMock {
    // This fallback is deliberately written so that if the buggy 'transfer' selector is used,
    // it will call this contract's own transfer which reverts (no balance).
    fallback(bytes calldata) external returns (bytes memory) {
        // If it's the 'transferFrom' selector (0x23b872dd), do nothing (success, no revert)
        if (msg.sig == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
            return "";
        }
        // Otherwise (including buggy 'transfer' selector), call this contract's own transfer which reverts
        revert("unexpected call");
    }
}

