pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Scenario: call transfer with a non-empty array (tos = [address(this)])
        // Reference: require(_tos.length > 0) passes, loop runs, returns true
        // Buggy: require(_tos.length == 0) reverts
        address[] memory tos = new address[](1);
        tos[0] = address(this);

        bool ok;
        try c.transfer(address(0), address(0), tos, 0) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: ok == true, buggy: ok == false
        assertTrue(ok);
    }
}

